import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"概览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1794214508000}'),n={name:"guide/overview.md"};function d(l,e,i,p,c,r){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h1><p>周报管理系统支持在不重新构建客户端的前提下扩展样式、插件脚本和 Vue 组件。所有扩展都放在应用资源目录中，保存后即时生效。</p><h2 id="三种扩展方式" tabindex="-1">三种扩展方式 <a class="header-anchor" href="#三种扩展方式" aria-label="Permalink to &quot;三种扩展方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>目录</th><th>生效方式</th></tr></thead><tbody><tr><td>外部组件</td><td><code>extensions</code> / AppData 插件目录</td><td>独立包构建后运行时注册</td></tr><tr><td>插件脚本</td><td><code>resources/js</code></td><td>重新加载应用</td></tr><tr><td>全局样式</td><td><code>resources/css</code></td><td>重新加载应用</td></tr></tbody></table><h2 id="运行架构" tabindex="-1">运行架构 <a class="header-anchor" href="#运行架构" aria-label="Permalink to &quot;运行架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tauri WebView（只负责显示）</span></span>
<span class="line"><span>        │  http://127.0.0.1:34115</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Cordis Node 服务（server/）</span></span>
<span class="line"><span>  ├─ 真实 @cordisjs/plugin-loader</span></span>
<span class="line"><span>  ├─ profile: package.json / cordis.yml / cordis.patch.yml / node_modules</span></span>
<span class="line"><span>  ├─ SQLite（node:sqlite）+ /api/db RPC</span></span>
<span class="line"><span>  ├─ /api/boot 下发 client bundle 清单</span></span>
<span class="line"><span>  └─ 静态托管 dist 与运行时资源</span></span>
<span class="line"><span>        │  /client/&lt;name&gt;/index.js</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>浏览器 client bundle（IIFE，Vue / Element Plus 用宿主 window 实例）</span></span></code></pre></div><ul><li>启动：Tauri 启动 Node 服务 → 等待服务返回地址 → WebView 打开该地址。</li><li>配置：Node 侧组合 profile bundles / patches，用真实 Loader 挂载插件。</li><li>客户端：浏览器读取 <code>/api/boot</code>，加载组件包并注册到 <code>window.weekReport</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">与 DSH 的差异</p><p>DSH 是纯 Node 进程 + Web 前端；这里是 Tauri 窗口 + Node 服务。 profile 组合和 client modules 是 DSH 语义的最小实现，不是直接复用 DSH app-boot。 <code>profile</code> 是真实 pnpm 项目：组件包先 <code>pnpm pack</code> 成 tarball，和 <code>vue</code> / <code>element-plus</code> 一起由 <code>pnpm install</code> 安装到 <code>src-tauri/target/profile/node_modules</code>。</p></div><h2 id="装配顺序" tabindex="-1">装配顺序 <a class="header-anchor" href="#装配顺序" aria-label="Permalink to &quot;装配顺序&quot;">​</a></h2><ol><li>安装内置能力并暴露 <code>window.weekReport</code>。</li><li>按文件名顺序注入 <code>resources/css/*.css</code>。</li><li>按文件名顺序加载 <code>resources/js/*.js</code>。</li><li>Node 服务用真实 Cordis Loader 组合 <code>profile</code>（首次启动复制到 <code>%APPDATA%/com.lu.week-report/profile</code>）：bundle patches → 用户 patch，按包名从 <code>node_modules</code> 挂载。</li><li>挂载 Vue 应用；插件脚本执行时 API 已就绪。</li></ol><div class="tip custom-block"><p class="custom-block-title">热加载</p><p>外部组件包由项目自己构建，宿主在启动时通过 Cordis profile 注册；内置 profile 随应用打包，用户 profile 在 %APPDATA%/com.lu.week-report/profile。</p></div><h2 id="api-版本" tabindex="-1">API 版本 <a class="header-anchor" href="#api-版本" aria-label="Permalink to &quot;API 版本&quot;">​</a></h2><p>当前 API 版本为 <strong>2</strong>，入口是 <code>window.weekReport</code>。完整字段参考见 <a href="/docs/guide/api.html">API 参考</a>。</p>`,13)])])}const b=a(n,[["render",d]]);export{h as __pageData,b as default};
